import { useEffect, useMemo, useState } from "react";
import { categoryLabels, formatCurrency, products } from "./data/products";
import { supabase, supabaseConfigured } from "./lib/supabase";
import { defaultNavigation, defaultSettings } from "./config/site";
import ModernLanding from "./themes/modern/ModernLanding";
import MinimalLanding from "./themes/minimal/MinimalLanding";
import BrandsStrip from "./components/BrandsStrip";
import BusinessMap from "./components/BusinessMap";
import Mercato from "./themes/Mercato/Mercato";
import PromotionModule from "./components/PromotionModule";

const categories = ["todos", "puertas", "ventanas", "aluminio", "pvc", "madera", "bano", "outlet"];

function useCart() {
  const [cart, setCart] = useState(() => { const saved = JSON.parse(localStorage.getItem("santaFeCart") || "{}"); return Object.fromEntries(Object.entries(saved).map(([id, value]) => [id, typeof value === "number" ? { product: products.find((product) => product.id === id), quantity: value } : value]).filter(([, value]) => value?.product)); });
  useEffect(() => localStorage.setItem("santaFeCart", JSON.stringify(cart)), [cart]);
  const add = (product, quantity = 1) => setCart((current) => ({ ...current, [product.id]: { product, quantity: (current[product.id]?.quantity || 0) + quantity } }));
  const remove = (id) => setCart((current) => { const next = { ...current }; next[id]?.quantity > 1 ? next[id] = { ...next[id], quantity: next[id].quantity - 1 } : delete next[id]; return next; });
  const lines = Object.values(cart);
  const clear = () => setCart({});
  return { add, remove, clear, lines, count: lines.reduce((sum, line) => sum + line.quantity, 0), total: lines.reduce((sum, line) => sum + line.product.price * line.quantity, 0) };
}

function Header({ onCart, count, search, setSearch, settings = defaultSettings, navigation = [] }) {
  const [menuOpen, setMenuOpen] = useState(false);
  const menu = navigation.length ? navigation : defaultNavigation;
  function menuHref(item) { const href = (item.href || "#productos").trim(); return href.startsWith("#") || href.startsWith("/") || href.startsWith("http") || href.startsWith("mailto:") ? href : `#${href}`; }
  function navigate(event, item) { const href = menuHref(item); setMenuOpen(false); if (!href.startsWith("#")) return; const target = document.querySelector(href); if (target) { event.preventDefault(); target.scrollIntoView({ behavior: "smooth", block: "start" }); } else { event.preventDefault(); window.location.href = `/${href}`; } }
  return <>{settings.top_bar_enabled !== false && <div className={`top-strip ${settings.top_bar_text ? "top-strip-moving" : ""}`}>{settings.top_bar_text ? <span className="top-strip-marquee"><b>{settings.top_bar_text}</b><b aria-hidden="true">{settings.top_bar_text}</b></span> : <><span>{settings.phone || "PARA VENTAS Y CONSULTAS"}</span><span>{settings.schedule || "AMPLIO STOCK EN LOCAL"}</span><span>ABERTURAS DE ALUMINIO, PVC Y MADERA</span></>}</div>}<header className="site-header"><button className="menu-button" onClick={() => setMenuOpen(!menuOpen)} aria-label="Abrir menú">☰</button><a className="brand" href="#inicio"><img src={settings.logo_url || defaultSettings.logo_url} alt={settings.business_name} /></a><div className="search-box"><input value={setSearch ? (search || "") : undefined} onChange={(event) => setSearch?.(event.target.value)} placeholder="Buscar productos" /><button>⌕</button></div><button className="cart-button" onClick={onCart}>🛒<span>{count}</span></button></header><nav className={`main-nav ${menuOpen ? "open" : ""}`}>{menu.map((item) => <a key={item.id || item.label} href={menuHref(item)} onClick={(event) => navigate(event, item)}>{item.label}</a>)}{settings.promotion_enabled && settings.promotion_image_url && <a href="#promociones" onClick={() => setMenuOpen(false)}>Promociones</a>}<a href="/admin/login" onClick={() => setMenuOpen(false)}>Administrar</a></nav></>;
}

function WhatsAppButton({ number }) {
  if (!number) return null;
  const digits = number.replace(/\D/g, "");
  const phone = digits.startsWith("54") ? digits : digits.startsWith("0") ? `54${digits.slice(1)}` : `54${digits}`;
  const message = encodeURIComponent("Hola, quiero consultar por un producto de Aberturas Santa Fe.");
  return <a className="whatsapp-float" href={`https://wa.me/${phone}?text=${message}`} target="_blank" rel="noreferrer" aria-label="Contactar por WhatsApp"><span className="whatsapp-tooltip">¿Necesitás ayuda?</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.5 3.5A11.8 11.8 0 0 0 12.08 0C5.54 0 .21 5.32.21 11.87c0 2.09.55 4.13 1.59 5.92L.1 24l6.36-1.67a11.85 11.85 0 0 0 5.62 1.43h.01c6.54 0 11.87-5.32 11.87-11.87 0-3.17-1.23-6.15-3.46-8.39ZM12.09 21.7c-1.76 0-3.48-.47-4.99-1.36l-.36-.21-3.77.99 1.01-3.67-.23-.38a9.83 9.83 0 1 1 8.34 4.63Zm5.4-7.38c-.3-.15-1.76-.87-2.03-.97-.27-.1-.47-.15-.67.15-.2.3-.77.97-.94 1.17-.17.2-.35.22-.65.07-.3-.15-1.26-.46-2.4-1.47-.89-.79-1.49-1.77-1.66-2.07-.17-.3-.02-.46.13-.61.14-.14.3-.35.45-.52.15-.17.2-.3.3-.5.1-.2.05-.37-.02-.52-.07-.15-.67-1.61-.92-2.2-.24-.58-.49-.5-.67-.51h-.57c-.2 0-.52.07-.8.37-.27.3-1.04 1.01-1.04 2.47s1.07 2.87 1.22 3.07c.15.2 2.1 3.21 5.09 4.5.71.31 1.26.49 1.69.63.71.23 1.36.2 1.87.12.57-.08 1.76-.72 2.01-1.41.25-.69.25-1.28.17-1.41-.07-.12-.27-.2-.57-.35Z" /></svg></a>;
}

function ProductCard({ product, onAdd, logo }) {
  const slug = product.slug || product.id;
  return <article className="product-card">{product.badge && <span className="product-badge">{product.badge}</span>}<a className="product-image-link" href={`/producto/${slug}`}><img src={product.image} alt={product.name} />{logo && <img className="product-watermark" src={logo} alt="" />}<span className="zoom-icon" aria-label="Ver producto">⌕</span></a><div className="product-body"><small>{product.category}</small><h3><a href={`/producto/${slug}`}>{product.name}</a></h3><p>{product.description}</p></div><div className="price-block">{product.oldPrice && <span className="old-price">{formatCurrency(product.oldPrice)}</span>}<strong>{formatCurrency(product.price)}</strong></div><footer><a className="view-button" href={`/producto/${slug}`}>Ver detalles</a><button className="add-button" onClick={onAdd}>Agregar al carrito</button></footer></article>;
}

function Cart({ cart, close }) {
  return <aside className="cart-drawer open"><div className="cart-panel"><div className="cart-head"><div><span>Tu selección</span><strong>{cart.count} {cart.count === 1 ? "producto" : "productos"}</strong></div><button onClick={close}>×</button></div><div className="cart-items">{cart.lines.length ? cart.lines.map(({ product, quantity }) => <div className="cart-line" key={product.id}><div><strong>{product.name}</strong><small>{quantity} × {formatCurrency(product.price)}</small></div><strong>{formatCurrency(product.price * quantity)}</strong><button onClick={() => cart.remove(product.id)}>−</button></div>) : <p className="empty-cart">Todavía no agregaste productos.</p>}</div><div className="cart-total"><span>Total estimado</span><strong>{formatCurrency(cart.total)}</strong></div><a className={`checkout-button ${!cart.lines.length ? "disabled" : ""}`} href={cart.lines.length ? "/checkout" : "#"} onClick={(event) => { if (!cart.lines.length) event.preventDefault(); close(); }}>Continuar compra →</a></div></aside>;
}

function Checkout() {
  const cart = useCart(); const [form, setForm] = useState({ name: "", phone: "", email: "", address: "", delivery: "Retiro en local", notes: "" }); const [status, setStatus] = useState("idle"); const [quoteId, setQuoteId] = useState(""); const [error, setError] = useState("");
  function updateForm(event) { setForm({ ...form, [event.target.name]: event.target.value }); }
  async function submit(event) { event.preventDefault(); if (!cart.lines.length) return; setStatus("sending"); setError(""); if (!supabase) { setError("No se pudo conectar con el sistema de pedidos."); setStatus("idle"); return; } const { data: quote, error: quoteError } = await supabase.from("quotes").insert({ customer_name: form.name, customer_phone: form.phone, customer_email: form.email || null, customer_address: form.address || null, delivery_method: form.delivery, notes: form.notes || null, total: cart.total }).select().single(); if (quoteError) { setError(quoteError.message); setStatus("idle"); return; } const { error: itemsError } = await supabase.from("quote_items").insert(cart.lines.map(({ product, quantity }) => ({ quote_id: quote.id, product_id: String(product.id), product_name: product.name, quantity, unit_price: product.price }))); if (itemsError) { setError(itemsError.message); setStatus("idle"); return; } setQuoteId(quote.id.slice(0, 8).toUpperCase()); cart.clear(); setStatus("success"); }
  if (status === "success") return <div className="checkout-page"><a className="auth-logo checkout-logo" href="/">ABERTURAS SANTA FE</a><div className="checkout-success"><div className="success-mark">✓</div><span className="section-kicker">Solicitud recibida</span><h1>¡Gracias por tu consulta!</h1><p>Registramos tu selección con el número <strong>#{quoteId}</strong>. Nos vamos a contactar para confirmar stock, medidas y entrega.</p><a className="checkout-back" href="/">Volver a la tienda →</a></div></div>;
  return <div className="checkout-page"><header className="checkout-header"><a className="auth-logo" href="/">ABERTURAS SANTA FE</a><span>Compra segura · Atención personalizada</span></header><main className="checkout-layout"><section className="checkout-form-wrap"><a className="breadcrumb" href="/">← Volver a la tienda</a><span className="section-kicker">Último paso</span><h1>Completá tu consulta.</h1><p>Te contactaremos para confirmar disponibilidad y preparar tu cotización.</p><form className="checkout-form" onSubmit={submit}><div className="checkout-fields"><label>Nombre completo<input name="name" required value={form.name} onChange={updateForm} placeholder="Tu nombre" /></label><label>WhatsApp / teléfono<input name="phone" required value={form.phone} onChange={updateForm} placeholder="+54 9 ..." /></label></div><label>Email <span>(opcional)</span><input name="email" type="email" value={form.email} onChange={updateForm} placeholder="tu@email.com" /></label><label>Forma de entrega<select name="delivery" value={form.delivery} onChange={updateForm}><option>Retiro en local</option><option>Envío a domicilio</option><option>A coordinar</option></select></label><label>Dirección <span>(si elegís envío)</span><input name="address" value={form.address} onChange={updateForm} placeholder="Localidad y dirección" /></label><label>Mensaje adicional<textarea name="notes" rows="4" value={form.notes} onChange={updateForm} placeholder="Medidas, color o cualquier detalle de tu proyecto" /></label>{error && <div className="form-error">{error}</div>}<button className="checkout-submit" disabled={status === "sending"}>{status === "sending" ? "Enviando solicitud…" : "Enviar solicitud de compra →"}</button></form></section><aside className="checkout-summary"><h2>Tu selección</h2>{cart.lines.map(({ product, quantity }) => <div className="summary-line" key={product.id}><div><strong>{product.name}</strong><span>{quantity} × {formatCurrency(product.price)}</span></div><strong>{formatCurrency(product.price * quantity)}</strong></div>)}<div className="summary-total"><span>Total estimado</span><strong>{formatCurrency(cart.total)}</strong></div><small>El total puede variar según medidas, terminaciones y costo de entrega.</small></aside></main></div>;
}

function ProductDetail({ slug }) {
  const cart = useCart(); const [product, setProduct] = useState(() => products.find((item) => item.slug === slug || item.id === slug)); const [settings, setSettings] = useState(defaultSettings); const [activeImage, setActiveImage] = useState(0); const [quantity, setQuantity] = useState(1); const [cartOpen, setCartOpen] = useState(false); const [loading, setLoading] = useState(Boolean(supabase));
  useEffect(() => { if (!supabase) return; Promise.all([supabase.from("products").select("*, categories(name, slug)").eq("slug", slug).eq("published", true).maybeSingle(), supabase.from("site_settings").select("*").eq("id", 1).maybeSingle()]).then(([productResult, settingsResult]) => { if (productResult.data) setProduct({ ...productResult.data, category: productResult.data.categories?.name || productResult.data.category, image: productResult.data.image_urls?.[0] || productResult.data.image_url }); if (settingsResult.data) setSettings({ ...defaultSettings, ...settingsResult.data }); setLoading(false); }); }, [slug]);
  if (loading) return <div className="loading">Cargando producto…</div>;
  if (!product) return <><Header count={cart.count} onCart={() => setCartOpen(true)} /><div className="not-found"><h1>Producto no encontrado</h1><a href="/">Volver a la tienda</a></div></>;
  const images = product.image_urls?.length ? product.image_urls : [product.image].filter(Boolean); const addProduct = () => { cart.add(product, quantity); setCartOpen(true); };
  return <><Header count={cart.count} onCart={() => setCartOpen(true)} settings={settings} /><main className="detail-page"><a className="breadcrumb" href="/#productos">← Volver al catálogo</a><div className="product-detail"><div className="detail-gallery"><div className="detail-main-image"><img src={images[activeImage]} alt={product.name} />{settings.logo_url && <img className="detail-watermark" src={settings.logo_url} alt="" />}</div><div className="detail-thumbs">{images.map((image, index) => <button className={activeImage === index ? "active" : ""} key={image} onClick={() => setActiveImage(index)}><img src={image} alt={`${product.name} vista ${index + 1}`} /></button>)}</div></div><section className="detail-info"><span className="detail-category">{product.category}</span><h1>{product.name}</h1><p className="detail-description">{product.description}</p>{product.promo_text && <div className="product-promo">✦ {product.promo_text}</div>}{product.old_price && <span className="detail-old-price">Precio anterior: {formatCurrency(product.old_price)}</span>}<strong className="detail-price">{formatCurrency(product.price)}</strong><div className="detail-divider" /><div className="purchase-row"><div className="quantity-control"><button onClick={() => setQuantity(Math.max(1, quantity - 1))}>−</button><span>{quantity}</span><button onClick={() => setQuantity(quantity + 1)}>+</button></div><button className="detail-add" onClick={addProduct}>Agregar al carrito</button></div><div className="delivery-box"><strong>🚚 Formas de entrega</strong><p>{product.delivery_info || "Retiro en local o envío a coordinar"}</p><small>Consultá disponibilidad y costo según tu localidad.</small></div><div className="detail-benefits"><span>✓ Compra segura</span><span>✓ Atención personalizada</span><span>✓ Cotización sin compromiso</span></div></section></div><section className="detail-bottom"><span className="section-kicker">Más información</span><h2>Una abertura pensada para tu proyecto.</h2><p>Las medidas, colores y terminaciones pueden personalizarse. Sumá el producto a tu selección y te ayudamos a definir cada detalle.</p></section></main>{cartOpen && <Cart cart={cart} close={() => setCartOpen(false)} />}</>;
}

function Landing() {
  const cart = useCart();
  const [category, setCategory] = useState("todos");
  const [cartOpen, setCartOpen] = useState(false);
  const [search, setSearch] = useState("");
  const [settings, setSettings] = useState(defaultSettings); const [navigation, setNavigation] = useState([]);
  const [brands, setBrands] = useState([]);
  const [catalogProducts, setCatalogProducts] = useState(products); const [catalogCategories, setCatalogCategories] = useState(categories.map((slug) => ({ slug, name: categoryLabels[slug] })));
  useEffect(() => { const root = document.documentElement; root.style.setProperty("--blue", settings.primary_color || defaultSettings.primary_color); root.style.setProperty("--blue-dark", settings.secondary_color || defaultSettings.secondary_color); root.style.setProperty("--orange", settings.accent_color || defaultSettings.accent_color); root.style.setProperty("--red", settings.danger_color || defaultSettings.danger_color); }, [settings]);
  useEffect(() => { if (!supabase) return; Promise.all([supabase.from("products").select("*, categories(name, slug), brands(name, slug)").eq("published", true).order("created_at", { ascending: false }), supabase.from("categories").select("name, slug").eq("active", true).order("sort_order"), supabase.from("site_settings").select("*").eq("id", 1).maybeSingle(), supabase.from("navigation_items").select("*").eq("active", true).order("sort_order"), supabase.from("brands").select("*").eq("active", true).order("sort_order")]).then(([productResult, categoryResult, settingsResult, navigationResult, brandsResult]) => { if (!productResult.error && productResult.data?.length) setCatalogProducts(productResult.data.map((item) => ({ ...item, category: item.categories?.slug || item.category, tags: item.tags || [], image: item.image_urls?.[0] || item.image_url }))); if (!categoryResult.error && categoryResult.data?.length) setCatalogCategories(categoryResult.data); if (!settingsResult.error && settingsResult.data) setSettings({ ...defaultSettings, ...settingsResult.data }); if (!navigationResult.error && navigationResult.data?.length) setNavigation(navigationResult.data); if (!brandsResult.error) setBrands(brandsResult.data || []); }); }, []);
  const visible = useMemo(() => catalogProducts.filter((product) => (category === "todos" || product.category === category || product.tags?.includes(category)) && product.name.toLowerCase().includes(search.toLowerCase())), [catalogProducts, category, search]);
  const themeProps = { Header, ProductCard, WhatsAppButton, BrandsStrip, BusinessMap, PromotionModule, Cart, cart, cartOpen, setCartOpen, search, setSearch, settings, navigation, category, setCategory, catalogCategories, visible, brands };
  if (settings.theme === "mercato") return <Mercato {...themeProps} />;
  return settings.theme === "minimal" ? <MinimalLanding {...themeProps} /> : <ModernLanding {...themeProps} />;
}

function Login() {
  const [email, setEmail] = useState(""); const [password, setPassword] = useState(""); const [error, setError] = useState(""); const [loading, setLoading] = useState(false);
  async function submit(event) { event.preventDefault(); setError(""); if (!supabaseConfigured) { setError("Configurá las variables de Supabase antes de iniciar sesión."); return; } setLoading(true); const { error: loginError } = await supabase.auth.signInWithPassword({ email: email.trim(), password }); setLoading(false); if (loginError) { const messages = { "Invalid login credentials": "El email o la contraseña no coinciden con un usuario de este proyecto Supabase.", "Email not confirmed": "El email todavía no fue confirmado. Activá Auto Confirm User en Supabase o confirmá el email recibido.", "Invalid API key": "La clave de Supabase configurada en Vercel no es válida." }; setError(messages[loginError.message] || `Supabase: ${loginError.message}`); } else window.location.href = "/admin"; }
  return <div className="auth-page"><a className="auth-logo" href="/">ABERTURAS SANTA FE</a><form className="auth-card" onSubmit={submit}><span className="section-kicker">Panel privado</span><h1>Ingresar al dashboard</h1><p>Administrá productos, consultas y contenido de la tienda.</p><label>Email<input type="email" required value={email} onChange={(event) => setEmail(event.target.value)} /></label><label>Contraseña<input type="password" required value={password} onChange={(event) => setPassword(event.target.value)} /></label>{error && <div className="form-error">{error}</div>}<button disabled={loading}>{loading ? "Ingresando..." : "Ingresar →"}</button><a href="/">← Volver a la tienda</a></form></div>;
}

function ResetPassword() {
  const [password, setPassword] = useState(""); const [confirm, setConfirm] = useState(""); const [message, setMessage] = useState(""); const [saving, setSaving] = useState(false);
  async function submit(event) { event.preventDefault(); if (password.length < 8) return setMessage("La contraseña debe tener al menos 8 caracteres."); if (password !== confirm) return setMessage("Las contraseñas no coinciden."); setSaving(true); const { error } = await supabase.auth.updateUser({ password }); setSaving(false); if (error) setMessage(error.message); else setMessage("Contraseña actualizada. Ya podés ingresar al panel."); }
  return <div className="auth-page"><a className="auth-logo" href="/">ABERTURAS SANTA FE</a><form className="auth-card" onSubmit={submit}><span className="section-kicker">Seguridad</span><h1>Restablecer contraseña</h1><p>Elegí una nueva contraseña para tu cuenta.</p><label>Nueva contraseña<input type="password" minLength="8" required value={password} onChange={(event) => setPassword(event.target.value)} /></label><label>Repetir contraseña<input type="password" minLength="8" required value={confirm} onChange={(event) => setConfirm(event.target.value)} /></label>{message && <div className="form-message">{message}</div>}<button disabled={saving}>{saving ? "Guardando…" : "Actualizar contraseña →"}</button><a href="/admin/login">Volver al login</a></form></div>;
}

function DashboardNav({ children }) {
  const [email, setEmail] = useState("");
  const [role, setRole] = useState("");
  const [ready, setReady] = useState(false);
  useEffect(() => { if (!supabase) { setReady(true); return; } supabase.auth.getUser().then(async ({ data }) => { if (!data.user) window.location.href = "/admin/login"; else { setEmail(data.user.email); const { data: profile } = await supabase.from("profiles").select("role").eq("id", data.user.id).maybeSingle(); setRole(profile?.role || "editor"); setReady(true); } }); }, []);
  async function logout() { await supabase?.auth.signOut(); window.location.href = "/admin/login"; }
  if (!ready) return <div className="loading">Cargando panel…</div>;
  return <div className="dashboard"><aside className="dashboard-nav"><a className="auth-logo" href="/">ABERTURAS<br />SANTA FE</a><span>ADMINISTRACIÓN</span><a className={window.location.pathname === "/admin" ? "selected" : ""} href="/admin">Resumen</a><a className={window.location.pathname === "/admin/products" ? "selected" : ""} href="/admin/products">Productos</a><a className={window.location.pathname === "/admin/categories" ? "selected" : ""} href="/admin/categories">Categorías</a><a className={window.location.pathname === "/admin/brands" ? "selected" : ""} href="/admin/brands">Marcas</a><a className={window.location.pathname === "/admin/promotions" ? "selected" : ""} href="/admin/promotions">Promociones</a><a className={window.location.pathname === "/admin/quotes" ? "selected" : ""} href="/admin/quotes">Consultas</a>{role === "admin" && <><a className={window.location.pathname === "/admin/users" ? "selected" : ""} href="/admin/users">Usuarios</a><a className={window.location.pathname === "/admin/settings" ? "selected" : ""} href="/admin/settings">Configuración</a></>}<button onClick={logout}>Cerrar sesión</button></aside><section className="dashboard-content"><header><div><span className="section-kicker">Panel de control</span><h1>{email ? email.split("@")[0] : "Administración"}</h1></div><a href="/" className="store-link">Ver tienda ↗</a></header>{children}</section></div>;
}

function AdminProducts() {
  const [items, setItems] = useState([]); const [categoryOptions, setCategoryOptions] = useState([]); const [brandOptions, setBrandOptions] = useState([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(""); const [saving, setSaving] = useState(false); const [files, setFiles] = useState([]); const [editingId, setEditingId] = useState(null); const [existingImages, setExistingImages] = useState([]); const [form, setForm] = useState({ name: "", category_id: "", brand_id: "", price: "", description: "", delivery_info: "Retiro en local o envío a coordinar", promo_text: "", image_url: "", stock: "0" });
  async function loadProducts() { if (!supabase) { setError("Supabase todavía no está configurado."); setLoading(false); return; } const [{ data, error: loadError }, { data: categoryData, error: categoryError }, { data: brandData, error: brandError }] = await Promise.all([supabase.from("products").select("*, categories(name, slug), brands(name, slug)").order("created_at", { ascending: false }), supabase.from("categories").select("id, name, slug").eq("active", true).order("sort_order"), supabase.from("brands").select("id, name, slug").eq("active", true).order("sort_order")]); if (loadError || categoryError || brandError) setError((loadError || categoryError || brandError).message); else { setItems(data || []); setCategoryOptions(categoryData || []); setBrandOptions(brandData || []); if (!form.category_id && categoryData?.[0]) setForm((current) => ({ ...current, category_id: categoryData[0].id })); } setLoading(false); }
  useEffect(() => { loadProducts(); }, []);
  function updateForm(event) { setForm({ ...form, [event.target.name]: event.target.value }); }
  function selectFiles(event) { const selected = [...event.target.files].filter((file) => file.type.startsWith("image/")); setError(selected.length > 5 ? "Solo se tomarán las primeras 5 imágenes." : ""); setFiles(selected.slice(0, 5)); }
  async function uploadImages(slug) { if (!files.length) return form.image_url ? [form.image_url] : []; const uploaded = []; for (const [index, file] of files.entries()) { const extension = file.name.split(".").pop().toLowerCase(); const path = `${slug}/${Date.now()}-${index}.${extension}`; const { error: uploadError } = await supabase.storage.from("product-images").upload(path, file, { upsert: false, contentType: file.type }); if (uploadError) throw uploadError; const { data } = supabase.storage.from("product-images").getPublicUrl(path); uploaded.push(data.publicUrl); } return uploaded; }
  function resetForm() { setEditingId(null); setExistingImages([]); setFiles([]); setForm({ name: "", category_id: categoryOptions[0]?.id || "", brand_id: "", price: "", description: "", delivery_info: "Retiro en local o envío a coordinar", promo_text: "", image_url: "", stock: "0" }); }
  function startEdit(product) { setEditingId(product.id); setExistingImages(product.image_urls?.length ? product.image_urls : (product.image_url ? [product.image_url] : [])); setFiles([]); setForm({ name: product.name, category_id: product.category_id || categoryOptions.find((category) => category.slug === product.category)?.id || "", brand_id: product.brand_id || brandOptions.find((brand) => brand.slug === product.brands?.slug)?.id || "", price: product.price, description: product.description || "", delivery_info: product.delivery_info || "Retiro en local o envío a coordinar", promo_text: product.promo_text || "", image_url: product.image_url || "", stock: product.stock || "0" }); window.scrollTo({ top: 0, behavior: "smooth" }); }
  async function createProduct(event) { event.preventDefault(); setSaving(true); setError(""); try { if (!form.category_id) throw new Error("Primero creá y seleccioná una categoría."); const slug = form.name.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, ""); const selectedCategory = categoryOptions.find((category) => category.id === form.category_id); const imageUrls = files.length ? await uploadImages(slug) : (existingImages.length ? existingImages : (form.image_url ? [form.image_url] : [])); const payload = { name: form.name, category_id: form.category_id, brand_id: form.brand_id || null, category: selectedCategory?.slug || "", description: form.description, delivery_info: form.delivery_info, promo_text: form.promo_text || null, slug, price: Number(form.price), stock: Number(form.stock), image_url: imageUrls[0] || null, image_urls: imageUrls, updated_at: new Date().toISOString() }; const result = editingId ? await supabase.from("products").update(payload).eq("id", editingId) : await supabase.from("products").insert(payload); if (result.error) throw result.error; resetForm(); event.target.reset(); await loadProducts(); } catch (saveError) { setError(saveError.message); } finally { setSaving(false); } }
  async function deleteProduct(id) { if (!window.confirm("¿Eliminar este producto?")) return; const { error: deleteError } = await supabase.from("products").delete().eq("id", id); if (deleteError) setError(deleteError.message); else loadProducts(); }
  return <DashboardNav><div className="admin-toolbar"><div><span className="section-kicker">Catálogo</span><h2>Productos</h2><p>Administrá lo que aparece en la tienda online.</p></div></div><div className="product-admin-layout"><form className="product-form panel" onSubmit={createProduct}><h2>{editingId ? "Editar producto" : "Nuevo producto"}</h2>{editingId && <div className="editing-note">Editando producto existente <button type="button" onClick={resetForm}>Cancelar</button></div>}<label>Nombre<input name="name" required value={form.name} onChange={updateForm} placeholder="Ventana corrediza 120" /></label><label>Categoría<select name="category_id" required value={form.category_id} onChange={updateForm}><option value="">Seleccioná una categoría</option>{categoryOptions.map((category) => <option key={category.id} value={category.id}>{category.name}</option>)}</select></label>{!categoryOptions.length && <a className="category-warning" href="/admin/categories">Primero crear categorías →</a>}<label>Marca<select name="brand_id" value={form.brand_id} onChange={updateForm}><option value="">Sin marca</option>{brandOptions.map((brand) => <option key={brand.id} value={brand.id}>{brand.name}</option>)}</select></label><div className="form-row"><label>Precio<input name="price" required type="number" min="0" value={form.price} onChange={updateForm} /></label><label>Stock<input name="stock" type="number" min="0" value={form.stock} onChange={updateForm} /></label></div><label>Imágenes del producto <span className="field-hint">Mantené Ctrl para elegir varias · máximo 5</span><input name="images" type="file" accept="image/png,image/jpeg,image/webp" multiple onChange={selectFiles} />{files.length > 0 && <div className="selected-images"><small className="file-count">{files.length}/5 imágenes seleccionadas</small><div className="selected-image-grid">{files.map((file) => <img key={`${file.name}-${file.size}`} src={URL.createObjectURL(file)} alt={file.name} />)}</div></div>}{editingId && existingImages.length > 0 && !files.length && <small className="existing-images-note">{existingImages.length} imagen{existingImages.length === 1 ? " guardada" : "es guardadas"}. Seleccioná nuevas para reemplazarlas.</small>}</label><label>O usar imagen URL<input name="image_url" value={form.image_url} onChange={updateForm} placeholder="https://..." /></label><label>Descripción<textarea name="description" rows="4" value={form.description} onChange={updateForm} /></label><label>Promoción del producto <span className="field-hint">Opcional, se muestra destacada</span><input name="promo_text" value={form.promo_text} onChange={updateForm} placeholder="10% de descuento por pago contado" /></label><label>Formas de entrega<input name="delivery_info" value={form.delivery_info} onChange={updateForm} placeholder="Retiro en local o envío a coordinar" /></label>{error && <div className="form-error">{error}</div>}<button className="primary-link" disabled={saving}>{saving ? `Subiendo ${files.length || 1} imagen${files.length === 1 ? "" : "es"}…` : editingId ? "Guardar cambios →" : "Publicar producto →"}</button></form><div className="panel admin-list"><div className="panel-title"><h2>Catálogo actual</h2><span>{items.length} productos</span></div>{loading ? <p>Cargando productos…</p> : !items.length ? <p className="empty-cart">Todavía no hay productos en Supabase.</p> : items.map((product) => <div className="admin-product-row" key={product.id}>{product.image_url ? <img src={product.image_url} alt="" /> : <div className="image-placeholder">SF</div>}<div><strong>{product.name}</strong><small>{product.categories?.name || product.category} · {formatCurrency(product.price)} · {product.image_urls?.length || (product.image_url ? 1 : 0)} imagen{(product.image_urls?.length || (product.image_url ? 1 : 0)) === 1 ? "" : "es"}</small></div><button className="edit-button" onClick={() => startEdit(product)}>Editar</button><button onClick={() => deleteProduct(product.id)}>Eliminar</button></div>)}</div></div></DashboardNav>;
}

function AdminCategories() {
  const [items, setItems] = useState([]); const [name, setName] = useState(""); const [loading, setLoading] = useState(true); const [error, setError] = useState("");
  async function loadCategories() { if (!supabase) { setError("Supabase todavía no está configurado."); setLoading(false); return; } const { data, error: loadError } = await supabase.from("categories").select("*").order("sort_order").order("name"); if (loadError) setError(loadError.message); else setItems(data || []); setLoading(false); }
  useEffect(() => { loadCategories(); }, []);
  async function createCategory(event) { event.preventDefault(); setError(""); const slug = name.toLowerCase().trim().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, ""); const { error: saveError } = await supabase.from("categories").insert({ name: name.trim(), slug, sort_order: items.length + 1 }); if (saveError) setError(saveError.message); else { setName(""); loadCategories(); } }
  async function deleteCategory(id) { if (!window.confirm("¿Eliminar esta categoría? Los productos asociados quedarán sin categoría.")) return; const { error: deleteError } = await supabase.from("categories").delete().eq("id", id); if (deleteError) setError(deleteError.message); else loadCategories(); }
  return <DashboardNav><div className="admin-toolbar"><div><span className="section-kicker">Organización</span><h2>Categorías</h2><p>Creá las categorías que luego vas a asociar a cada producto.</p></div></div><div className="category-admin-layout"><form className="product-form panel" onSubmit={createCategory}><h2>Nueva categoría</h2><label>Nombre<input required value={name} onChange={(event) => setName(event.target.value)} placeholder="Ej. Aberturas especiales" /></label>{error && <div className="form-error">{error}</div>}<button className="primary-link">Crear categoría →</button></form><div className="panel admin-list"><div className="panel-title"><h2>Categorías disponibles</h2><span>{items.length} categorías</span></div>{loading ? <p>Cargando categorías…</p> : items.map((category) => <div className="admin-category-row" key={category.id}><div><strong>{category.name}</strong><small>/{category.slug}</small></div><button onClick={() => deleteCategory(category.id)}>Eliminar</button></div>)}</div></div><a className="store-link" href="/admin/products">← Volver a productos</a></DashboardNav>;
}

function AdminBrands() {
  const [brands, setBrands] = useState([]); const [name, setName] = useState(""); const [logo, setLogo] = useState(null); const [loading, setLoading] = useState(true); const [message, setMessage] = useState(""); const [saving, setSaving] = useState(false);
  async function loadBrands() { if (!supabase) { setLoading(false); return; } const { data, error } = await supabase.from("brands").select("*").order("sort_order").order("name"); if (error) setMessage(error.message); else setBrands(data || []); setLoading(false); }
  useEffect(() => { loadBrands(); }, []);
  async function createBrand(event) { event.preventDefault(); setSaving(true); setMessage(""); try { const slug = name.toLowerCase().trim().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, ""); let logoUrl = null; if (logo) { const extension = logo.name.split(".").pop().toLowerCase(); const path = `${slug}-${Date.now()}.${extension}`; const upload = await supabase.storage.from("brand-assets").upload(path, logo, { contentType: logo.type }); if (upload.error) throw upload.error; logoUrl = supabase.storage.from("brand-assets").getPublicUrl(path).data.publicUrl; } const { error } = await supabase.from("brands").insert({ name: name.trim(), slug, logo_url: logoUrl, sort_order: brands.length + 1 }); if (error) throw error; setName(""); setLogo(null); event.target.reset(); setMessage("Marca creada correctamente."); loadBrands(); } catch (error) { setMessage(error.message); } finally { setSaving(false); } }
  async function deleteBrand(brand) { if (!window.confirm(`¿Eliminar la marca ${brand.name}?`)) return; const { error } = await supabase.from("brands").delete().eq("id", brand.id); if (error) setMessage(error.message); else loadBrands(); }
  return <DashboardNav><div className="admin-toolbar"><div><span className="section-kicker">Catálogo</span><h2>Marcas</h2><p>Creá las marcas con las que trabaja el negocio y asociá sus logos.</p></div></div><div className="brands-admin-layout"><form className="product-form panel" onSubmit={createBrand}><h2>Nueva marca</h2><label>Nombre<input required value={name} onChange={(event) => setName(event.target.value)} placeholder="Ej. Aluar" /></label><label>Logo de la marca <span className="field-hint">PNG, JPG o WEBP</span><input type="file" accept="image/png,image/jpeg,image/webp" onChange={(event) => setLogo(event.target.files[0])} /></label>{message && <div className="form-message">{message}</div>}<button className="primary-link" disabled={saving}>{saving ? "Guardando…" : "Crear marca →"}</button></form><div className="panel admin-list"><div className="panel-title"><h2>Marcas disponibles</h2><span>{brands.length} marcas</span></div>{loading ? <p>Cargando marcas…</p> : !brands.length ? <p className="empty-cart">Todavía no hay marcas cargadas.</p> : brands.map((brand) => <div className="admin-brand-row" key={brand.id}>{brand.logo_url ? <img src={brand.logo_url} alt={brand.name} /> : <div className="image-placeholder">M</div>}<div><strong>{brand.name}</strong><small>/{brand.slug}</small></div><button className="danger-button" onClick={() => deleteBrand(brand)}>Eliminar</button></div>)}</div></div></DashboardNav>;
}

function SettingsAccess() {
  const [email, setEmail] = useState("diseartevt@gmail.com"); const [password, setPassword] = useState(""); const [error, setError] = useState(""); const [checking, setChecking] = useState(true); const [authorized, setAuthorized] = useState(false); const [loading, setLoading] = useState(false);
  useEffect(() => { if (!supabase) { setChecking(false); return; } supabase.auth.getUser().then(async ({ data }) => { if (data.user) { const { data: profile } = await supabase.from("profiles").select("role").eq("id", data.user.id).maybeSingle(); if (profile?.role === "admin") setAuthorized(true); } setChecking(false); }); }, []);
  async function submit(event) { event.preventDefault(); setLoading(true); setError(""); const { data, error: loginError } = await supabase.auth.signInWithPassword({ email: email.trim(), password }); if (loginError) setError("Email o contraseña incorrectos."); else { const { data: profile } = await supabase.from("profiles").select("role").eq("id", data.user.id).maybeSingle(); if (profile?.role === "admin") setAuthorized(true); else { await supabase.auth.signOut(); setError("Este usuario no tiene permisos para acceder a configuración."); } } setLoading(false); }
  if (checking) return <div className="loading">Verificando permisos…</div>;
  if (authorized) return <AdminSettings />;
  return <div className="settings-lock-page"><div className="settings-lock-modal"><div className="lock-icon">⌕</div><span className="section-kicker">Acceso restringido</span><h1>Configuración del negocio</h1><p>Esta sección solo está disponible para administradores.</p><form onSubmit={submit}><label>Email<input type="email" required value={email} onChange={(event) => setEmail(event.target.value)} /></label><label>Contraseña<input type="password" required value={password} onChange={(event) => setPassword(event.target.value)} /></label>{error && <div className="form-error">{error}</div>}<button disabled={loading}>{loading ? "Verificando…" : "Ingresar a configuración →"}</button></form><a href="/admin">← Volver al resumen</a></div></div>;
}

function AdminSettings() {
  const [form, setForm] = useState(defaultSettings); const [navigation, setNavigation] = useState([]); const [logoFile, setLogoFile] = useState(null); const [heroFile, setHeroFile] = useState(null); const [promotionFile, setPromotionFile] = useState(null); const [newMenu, setNewMenu] = useState({ label: "", href: "#productos" }); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [message, setMessage] = useState("");
  useEffect(() => { if (!supabase) { setLoading(false); return; } Promise.all([supabase.from("site_settings").select("*").eq("id", 1).maybeSingle(), supabase.from("navigation_items").select("*").order("sort_order")]).then(([settingsResult, navResult]) => { if (settingsResult.data) setForm({ ...defaultSettings, ...settingsResult.data }); if (navResult.data) setNavigation(navResult.data); setLoading(false); }); }, []);
  function updateForm(event) { setForm({ ...form, [event.target.name]: event.target.value }); }
  async function uploadAsset(file, folder) { if (!file) return null; const extension = file.name.split(".").pop().toLowerCase(); const path = `${folder}/${Date.now()}.${extension}`; const { error } = await supabase.storage.from("site-assets").upload(path, file, { upsert: true, contentType: file.type }); if (error) throw error; return supabase.storage.from("site-assets").getPublicUrl(path).data.publicUrl; }
  async function saveSettings(event) { event.preventDefault(); setSaving(true); setMessage(""); try { const logoUrl = await uploadAsset(logoFile, "logo"); const heroUrl = await uploadAsset(heroFile, "hero"); const promotionUrl = await uploadAsset(promotionFile, "promotion"); const payload = { ...form, logo_url: logoUrl || form.logo_url, hero_image_url: heroUrl || form.hero_image_url, promotion_image_url: promotionUrl || form.promotion_image_url, updated_at: new Date().toISOString() }; const { error } = await supabase.from("site_settings").upsert({ id: 1, ...payload }); if (error) throw error; setForm(payload); setLogoFile(null); setHeroFile(null); setPromotionFile(null); event.target.reset(); setMessage("Configuración guardada correctamente."); } catch (saveError) { setMessage(saveError.message); } finally { setSaving(false); } }
  async function addMenuItem(event) { event.preventDefault(); if (!newMenu.label.trim()) return; const { data, error } = await supabase.from("navigation_items").insert({ label: newMenu.label.trim(), href: newMenu.href, sort_order: navigation.length + 1 }).select().single(); if (error) setMessage(error.message); else { setNavigation([...navigation, data]); setNewMenu({ label: "", href: "#productos" }); } }
  async function saveMenuItem(item) { const { error } = await supabase.from("navigation_items").update({ label: item.label, href: item.href, active: item.active }).eq("id", item.id); if (error) setMessage(error.message); else setMessage("Menú actualizado."); }
  async function removeMenuItem(id) { if (!window.confirm("¿Quitar este item del menú?")) return; const { error } = await supabase.from("navigation_items").delete().eq("id", id); if (error) setMessage(error.message); else setNavigation(navigation.filter((item) => item.id !== id)); }
  if (loading) return <div className="loading">Cargando configuración…</div>;
  return <DashboardNav><div className="admin-toolbar"><div><span className="section-kicker">Identidad del negocio</span><h2>Configuración</h2><p>Estos datos se muestran en la landing y en las fichas de producto.</p></div></div><form className="settings-form" onSubmit={saveSettings}><div className="settings-grid"><section className="panel"><h2>Datos del negocio</h2><div className="form-row"><label>Nombre comercial<input name="business_name" value={form.business_name} onChange={updateForm} /></label><label>Email<input name="email" type="email" value={form.email} onChange={updateForm} /></label></div><div className="form-row"><label>Teléfono<input name="phone" value={form.phone} onChange={updateForm} /></label><label>WhatsApp<input name="whatsapp" value={form.whatsapp} onChange={updateForm} /></label></div><div className="form-row"><label>Dirección<input name="address" value={form.address} onChange={updateForm} /></label><label>Dirección para Google Maps<input name="map_query" value={form.map_query} onChange={updateForm} placeholder="Laprida 98, Santa Fe, Argentina" /></label></div><label>Horarios<input name="schedule" value={form.schedule} onChange={updateForm} /></label><label>Logo<input type="file" accept="image/png,image/jpeg,image/webp" onChange={(event) => setLogoFile(event.target.files[0])} /></label>{form.logo_url && <img className="settings-preview logo-preview" src={form.logo_url} alt="Logo actual" />}</section><section className="panel"><h2>Hero de la landing</h2><label>Texto pequeño<input name="hero_badge" value={form.hero_badge} onChange={updateForm} /></label><label>Título principal<input name="hero_title" value={form.hero_title} onChange={updateForm} /></label><label>Descripción<textarea name="hero_subtitle" rows="3" value={form.hero_subtitle} onChange={updateForm} /></label><label>Imagen principal<input type="file" accept="image/png,image/jpeg,image/webp" onChange={(event) => setHeroFile(event.target.files[0])} /></label>{form.hero_image_url && <img className="settings-preview hero-preview" src={form.hero_image_url} alt="Hero actual" />}</section><section className="panel"><h2>Barra superior</h2><p className="settings-helper">Configurá un mensaje animado en la franja superior de la landing.</p><label className="toggle-setting"><input name="top_bar_enabled" type="checkbox" checked={form.top_bar_enabled !== false} onChange={(event) => setForm({ ...form, top_bar_enabled: event.target.checked })} /><span>Mostrar barra superior</span></label><label>Texto animado<input name="top_bar_text" value={form.top_bar_text || ""} onChange={updateForm} placeholder="Envíos a todo el país · Consultá hoy" /></label></section><section className="panel"><h2>Marcas en la landing</h2><p className="settings-helper">Mostrá u ocultá la banda animada de marcas.</p><label className="toggle-setting"><input name="brands_enabled" type="checkbox" checked={Boolean(form.brands_enabled)} onChange={(event) => setForm({ ...form, brands_enabled: event.target.checked })} /><span>Mostrar marcas en la página principal</span></label></section><section className="panel"><h2>Mapa en la landing</h2><p className="settings-helper">Mostrá u ocultá el mapa de ubicación del comercio.</p><label className="toggle-setting"><input name="map_enabled" type="checkbox" checked={Boolean(form.map_enabled)} onChange={(event) => setForm({ ...form, map_enabled: event.target.checked })} /><span>Mostrar mapa en la página principal</span></label></section><section className="panel"><h2>Tema de la landing</h2><p className="settings-helper">Elegí la estructura visual para este cliente.</p><label>Diseño activo<select name="theme" value={form.theme} onChange={updateForm}><option value="modern">Modern</option><option value="minimal">Minimal</option><option value="mercato">Mercato</option></select></label></section><section className="panel"><h2>Identidad visual</h2><p className="settings-helper">Adaptá la paleta sin modificar el código de la landing.</p><div className="color-settings"><label>Principal<input name="primary_color" type="color" value={form.primary_color} onChange={updateForm} /></label><label>Oscuro<input name="secondary_color" type="color" value={form.secondary_color} onChange={updateForm} /></label><label>Acento<input name="accent_color" type="color" value={form.accent_color} onChange={updateForm} /></label><label>Promos<input name="danger_color" type="color" value={form.danger_color} onChange={updateForm} /></label></div></section><section className="panel"><h2>Sección de contacto</h2><label>Título<input name="contact_title" value={form.contact_title} onChange={updateForm} /></label><label>Descripción<textarea name="contact_subtitle" rows="3" value={form.contact_subtitle} onChange={updateForm} /></label></section></div>{message && <div className="form-message">{message}</div>}<button className="primary-link settings-save" disabled={saving}>{saving ? "Guardando archivos…" : "Guardar configuración →"}</button></form><section className="panel menu-admin"><div className="panel-title"><div><h2>Menú de la landing</h2><p>Agregá, editá o quitá accesos de navegación.</p></div></div>{navigation.map((item) => <div className="menu-row" key={item.id}><input value={item.label} onChange={(event) => setNavigation(navigation.map((current) => current.id === item.id ? { ...current, label: event.target.value } : current))} /><input value={item.href} onChange={(event) => setNavigation(navigation.map((current) => current.id === item.id ? { ...current, href: event.target.value } : current))} /><button onClick={() => saveMenuItem(item)}>Guardar</button><button className="danger-button" onClick={() => removeMenuItem(item.id)}>Quitar</button></div>)}<form className="add-menu-row" onSubmit={addMenuItem}><input required value={newMenu.label} onChange={(event) => setNewMenu({ ...newMenu, label: event.target.value })} placeholder="Nuevo item" /><input value={newMenu.href} onChange={(event) => setNewMenu({ ...newMenu, href: event.target.value })} placeholder="#productos" /><button>Agregar item +</button></form></section></DashboardNav>;
}

function AdminPromotions() {
  const [form, setForm] = useState(defaultSettings); const [products, setProducts] = useState([]); const [file, setFile] = useState(null); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [message, setMessage] = useState("");
  useEffect(() => { if (!supabase) { setLoading(false); return; } Promise.all([supabase.from("site_settings").select("*").eq("id", 1).maybeSingle(), supabase.from("products").select("id, name, slug, price, image_url, image_urls").eq("published", true).order("name")]).then(([settingsResult, productsResult]) => { if (settingsResult.data) setForm({ ...defaultSettings, ...settingsResult.data }); if (!productsResult.error) setProducts(productsResult.data || []); setLoading(false); }); }, []);
  function update(event) { const { name, value, type, checked } = event.target; setForm({ ...form, [name]: type === "checkbox" ? checked : value }); }
  function selectProduct(event) { const product = products.find((item) => item.id === event.target.value); setForm({ ...form, promotion_product_id: product?.id || "", promotion_link: product ? `/producto/${product.slug}` : "#productos" }); }
  async function uploadPromotion() { if (!file) return form.promotion_image_url; const extension = file.name.split(".").pop().toLowerCase(); const path = `promotion/${Date.now()}.${extension}`; const { error } = await supabase.storage.from("site-assets").upload(path, file, { upsert: true, contentType: file.type }); if (error) throw error; return supabase.storage.from("site-assets").getPublicUrl(path).data.publicUrl; }
  async function save(event) { event.preventDefault(); setSaving(true); setMessage(""); try { const imageUrl = await uploadPromotion(); const payload = { ...form, promotion_image_url: imageUrl, promotion_link: form.promotion_link || "#productos", promotion_product_id: form.promotion_product_id || null, updated_at: new Date().toISOString() }; const { error } = await supabase.from("site_settings").upsert({ id: 1, ...payload }); if (error) throw error; setForm(payload); setFile(null); event.target.reset(); setMessage("Promoción guardada correctamente."); } catch (error) { setMessage(error.message); } finally { setSaving(false); } }
  const selectedProduct = products.find((product) => product.id === form.promotion_product_id); const previewImage = form.promotion_image_url || selectedProduct?.image_urls?.[0] || selectedProduct?.image_url;
  if (loading) return <div className="loading">Cargando promoción…</div>;
  return <DashboardNav><div className="admin-toolbar"><div><span className="section-kicker">Contenido destacado</span><h2>Promociones</h2><p>Creá una promoción y vinculala directamente con un producto del catálogo.</p></div></div><form className="promotion-admin-form" onSubmit={save}><div className="promotion-editor"><section className="panel promotion-form-card"><div className="panel-title"><div><span className="section-kicker">Configuración</span><h2>Datos de la promoción</h2></div><span className={`promotion-status ${form.promotion_enabled ? "is-active" : ""}`}>{form.promotion_enabled ? "Activa" : "Inactiva"}</span></div><button type="button" className={`promotion-toggle-button ${form.promotion_enabled ? "is-active" : ""}`} onClick={() => setForm({ ...form, promotion_enabled: !form.promotion_enabled })}>{form.promotion_enabled ? "Desactivar promoción" : "Activar promoción"}</button><label className="toggle-setting"><input name="promotion_modal_enabled" type="checkbox" checked={form.promotion_modal_enabled !== false} onChange={update} /><span>Abrir como modal al cargar la página</span></label><label>Mostrar modal cada (minutos)<input name="promotion_modal_interval" type="number" min="0" value={form.promotion_modal_interval ?? 0} onChange={update} /><small className="field-hint">Usá 0 para mostrarlo en cada visita.</small></label><label>Título<input name="promotion_title" value={form.promotion_title || ""} onChange={update} placeholder="Oferta especial" /></label><label>Texto<textarea name="promotion_text" rows="4" value={form.promotion_text || ""} onChange={update} placeholder="Aprovechá esta promoción por tiempo limitado." /></label><label>Producto de la promoción<select value={form.promotion_product_id || ""} onChange={selectProduct}><option value="">Seleccioná un producto</option>{products.map((product) => <option key={product.id} value={product.id}>{product.name}</option>)}</select></label>{selectedProduct && <p className="promotion-selected-product">Destino: <strong>/producto/{selectedProduct.slug}</strong></p>}<label>Texto del botón<input name="promotion_button_label" value={form.promotion_button_label || "Ver promoción"} onChange={update} /></label><label>Imagen de promoción<input type="file" accept="image/png,image/jpeg,image/webp" onChange={(event) => setFile(event.target.files[0])} /></label>{form.promotion_image_url && <img className="settings-preview promotion-preview" src={form.promotion_image_url} alt="Promoción actual" />}</section><aside className="panel promotion-preview-card"><span className="section-kicker">Vista previa</span><h2>Así se verá tu promoción</h2>{previewImage ? <img src={previewImage} alt="Vista previa de promoción" /> : <div className="promotion-preview-empty">Subí una imagen para ver la promoción.</div>}<div><strong>{form.promotion_title || "Título de la promoción"}</strong><p>{form.promotion_text || "El texto de la promoción aparecerá aquí."}</p><button type="button" className="primary-link">{form.promotion_button_label || "Ver promoción"} →</button></div></aside></div>{message && <div className="form-message">{message}</div>}<button className="primary-link settings-save" disabled={saving}>{saving ? "Guardando promoción…" : "Guardar promoción →"}</button></form></DashboardNav>;
}
function AdminQuotes() {
  const [quotes, setQuotes] = useState([]); const [selected, setSelected] = useState(null); const [loading, setLoading] = useState(true); const [error, setError] = useState("");
  async function loadQuotes() { if (!supabase) { setError("Supabase todavía no está configurado."); setLoading(false); return; } const { data, error: loadError } = await supabase.from("quotes").select("*, quote_items(*)").order("created_at", { ascending: false }); if (loadError) setError(loadError.message); else setQuotes(data || []); setLoading(false); }
  useEffect(() => { loadQuotes(); }, []);
  async function updateStatus(id, status) { const { error: updateError } = await supabase.from("quotes").update({ status }).eq("id", id); if (updateError) setError(updateError.message); else { setQuotes(quotes.map((quote) => quote.id === id ? { ...quote, status } : quote)); if (selected?.id === id) setSelected({ ...selected, status }); } }
  const statusLabels = { new: "Nueva", contacted: "Contactada", quoted: "Cotizada", closed: "Cerrada", cancelled: "Cancelada" };
  return <DashboardNav><div className="admin-toolbar"><div><span className="section-kicker">Ventas y atención</span><h2>Consultas</h2><p>Solicitudes recibidas desde el carrito de la landing.</p></div><button className="refresh-button" onClick={loadQuotes}>Actualizar ↻</button></div>{error && <div className="form-error">{error}</div>}{loading ? <div className="panel">Cargando consultas…</div> : !quotes.length ? <div className="panel empty-admin"><h2>Todavía no hay consultas</h2><p>Las solicitudes realizadas desde el checkout aparecerán acá.</p></div> : <div className="quotes-layout"><div className="quotes-list">{quotes.map((quote) => <button className={`quote-row ${selected?.id === quote.id ? "selected" : ""}`} key={quote.id} onClick={() => setSelected(quote)}><div><strong>{quote.customer_name}</strong><span>{quote.customer_phone}</span></div><div><small>{new Date(quote.created_at).toLocaleDateString("es-AR")}</small><b className={`status status-${quote.status}`}>{statusLabels[quote.status] || quote.status}</b></div></button>)}</div><div className="quote-detail panel">{selected ? <><div className="quote-detail-head"><div><span className="section-kicker">Solicitud #{selected.id.slice(0, 8).toUpperCase()}</span><h2>{selected.customer_name}</h2><p>{new Date(selected.created_at).toLocaleString("es-AR")}</p></div><select value={selected.status} onChange={(event) => updateStatus(selected.id, event.target.value)}>{Object.entries(statusLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></div><div className="customer-contact"><span>☎ {selected.customer_phone}</span>{selected.customer_email && <span>✉ {selected.customer_email}</span>}{selected.customer_address && <span>⌂ {selected.customer_address}</span>}<span>🚚 {selected.delivery_method}</span></div><h3>Productos solicitados</h3><div className="quote-product-lines">{selected.quote_items?.map((item) => <div key={item.id}><span>{item.quantity} × {item.product_name}</span><strong>{formatCurrency(item.unit_price * item.quantity)}</strong></div>)}</div><div className="quote-total-admin"><span>Total estimado</span><strong>{formatCurrency(selected.total)}</strong></div>{selected.notes && <div className="quote-notes"><strong>Mensaje del cliente</strong><p>{selected.notes}</p></div>}</> : <div className="empty-detail">Seleccioná una consulta para ver todos sus datos.</div>}</div></div>}</DashboardNav>;
}

function AdminUsers() {
  const [users, setUsers] = useState([]); const [form, setForm] = useState({ full_name: "", email: "", password: "", role: "editor" }); const [editUser, setEditUser] = useState(null); const [message, setMessage] = useState(""); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false);
  async function loadUsers() { if (!supabase) { setLoading(false); return; } const { data, error } = await supabase.from("profiles").select("id, email, full_name, role, created_at").order("created_at"); if (error) setMessage(error.message); else setUsers(data || []); setLoading(false); }
  useEffect(() => { loadUsers(); }, []);
  function updateForm(event) { setForm({ ...form, [event.target.name]: event.target.value }); }
  async function createUser(event) { event.preventDefault(); setSaving(true); setMessage(""); const { data, error } = await supabase.functions.invoke("create-user", { body: form }); if (error) setMessage(error.message); else if (data?.error) setMessage(data.error); else { setMessage("Usuario creado correctamente."); setForm({ full_name: "", email: "", password: "", role: "editor" }); loadUsers(); } setSaving(false); }
  function startEdit(user) { setEditUser(user); setForm({ full_name: user.full_name || "", email: user.email || "", password: "", role: user.role }); setMessage(""); }
  function cancelEdit() { setEditUser(null); setForm({ full_name: "", email: "", password: "", role: "editor" }); setMessage(""); }
  async function saveUser(event) { event.preventDefault(); setSaving(true); setMessage(""); const { data, error } = await supabase.functions.invoke("manage-user", { body: { action: "update", user_id: editUser.id, full_name: form.full_name, role: form.role } }); if (error || data?.error) setMessage(error?.message || data.error); else { setMessage("Usuario actualizado."); cancelEdit(); loadUsers(); } setSaving(false); }
  async function deleteUser(user) { if (!window.confirm(`¿Eliminar a ${user.full_name || user.email}?`)) return; const { data, error } = await supabase.functions.invoke("manage-user", { body: { action: "delete", user_id: user.id } }); if (error || data?.error) setMessage(error?.message || data.error); else { setMessage("Usuario eliminado."); loadUsers(); } }
  async function resetPassword(user) { const { error } = await supabase.auth.resetPasswordForEmail(user.email, { redirectTo: `${window.location.origin}/admin/reset-password` }); setMessage(error ? error.message : `Enviamos un email de recuperación a ${user.email}.`); }
  return <DashboardNav><div className="admin-toolbar"><div><span className="section-kicker">Accesos y permisos</span><h2>Usuarios</h2><p>Creá cuentas, editá roles y administrá el acceso al panel.</p></div></div><div className="users-admin-layout"><form className="product-form panel" onSubmit={createUser}><h2>Nuevo usuario</h2><label>Nombre completo<input name="full_name" required value={form.full_name} onChange={updateForm} placeholder="Nombre del colaborador" /></label><label>Email<input name="email" type="email" required value={form.email} onChange={updateForm} placeholder="usuario@empresa.com" /></label><label>Contraseña<input name="password" type="password" minLength="8" required value={form.password} onChange={updateForm} placeholder="Mínimo 8 caracteres" /></label><label>Rol<select name="role" value={form.role} onChange={updateForm}><option value="editor">Editor — productos y consultas</option><option value="admin">Administrador — acceso total</option></select></label>{message && <div className="form-message">{message}</div>}<button className="primary-link" disabled={saving}>{saving ? "Creando usuario…" : "Crear usuario →"}</button></form><div className="panel admin-list"><div className="panel-title"><div><h2>Usuarios actuales</h2><p>Personas con acceso al panel de administración</p></div><span>{users.length} usuarios</span></div>{loading ? <p>Cargando usuarios…</p> : users.map((user) => <div className="admin-user-row" key={user.id}><div className="user-avatar">{(user.full_name || user.email || "U").slice(0, 1).toUpperCase()}</div>{editUser?.id === user.id ? <div className="user-edit-fields"><input value={editUser.full_name} onChange={(event) => setEditUser({ ...editUser, full_name: event.target.value })} /><select value={editUser.role} onChange={(event) => setEditUser({ ...editUser, role: event.target.value })}><option value="editor">Editor</option><option value="admin">Admin</option></select><button onClick={saveUser} disabled={saving}>✓ Guardar</button><button onClick={() => setEditUser(null)}>× Cancelar</button></div> : <><div><strong>{user.full_name || "Sin nombre"}</strong><small>{user.email || "Email pendiente"}</small></div><span className={`role-pill role-${user.role}`}>{user.role === "admin" ? "Administrador" : "Editor"}</span><div className="user-actions"><button title="Editar usuario" onClick={() => setEditUser({ ...user })}>✎ <span>Editar</span></button><button title="Enviar reset de contraseña" onClick={() => resetPassword(user)}>↻ <span>Resetear clave</span></button><button className="danger-button" title="Eliminar usuario" onClick={() => deleteUser(user)}>⌫ <span>Eliminar</span></button></div></>}</div>)}</div></div></DashboardNav>;
}

function AdminUsersPage() {
  const [users, setUsers] = useState([]); const [selected, setSelected] = useState(null); const [form, setForm] = useState({ full_name: "", email: "", password: "", role: "editor" }); const [message, setMessage] = useState(""); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false);
  async function loadUsers() { const { data, error } = await supabase.from("profiles").select("id, email, full_name, role, created_at").order("created_at"); if (error) setMessage(error.message); else setUsers(data || []); setLoading(false); }
  useEffect(() => { loadUsers(); }, []);
  function updateForm(event) { setForm({ ...form, [event.target.name]: event.target.value }); }
  function selectUser(user) { setSelected(user); setForm({ full_name: user.full_name || "", email: user.email || "", password: "", role: user.role }); setMessage(""); }
  function clearSelection() { setSelected(null); setForm({ full_name: "", email: "", password: "", role: "editor" }); setMessage(""); }
  async function submit(event) { event.preventDefault(); setSaving(true); setMessage(""); const request = selected ? supabase.functions.invoke("manage-user", { body: { action: "update", user_id: selected.id, full_name: form.full_name, role: form.role } }) : supabase.functions.invoke("create-user", { body: form }); const { data, error } = await request; if (error || data?.error) setMessage(error?.message || data.error); else { setMessage(selected ? "Usuario actualizado correctamente." : "Usuario creado correctamente."); clearSelection(); loadUsers(); } setSaving(false); }
  async function deleteUser(event, user) { event.stopPropagation(); if (!window.confirm(`¿Eliminar a ${user.full_name || user.email}?`)) return; const { data, error } = await supabase.functions.invoke("manage-user", { body: { action: "delete", user_id: user.id } }); if (error || data?.error) setMessage(error?.message || data.error); else { setMessage("Usuario eliminado."); if (selected?.id === user.id) clearSelection(); loadUsers(); } }
  async function resetPassword(event, user) { event.stopPropagation(); const { data, error } = await supabase.functions.invoke("manage-user", { body: { action: "reset", user_id: user.id, redirect_to: `${window.location.origin}/admin/reset-password` } }); if (error || data?.error) setMessage(error?.message || data.error); else if (data?.action_link) { window.open(data.action_link, "_blank", "noopener,noreferrer"); setMessage("Abrimos el enlace seguro de recuperación en una nueva pestaña."); } }
  return <DashboardNav><div className="admin-toolbar"><div><span className="section-kicker">Accesos y permisos</span><h2>Usuarios</h2><p>Seleccioná un usuario para modificar sus datos desde el formulario.</p></div></div><div className="users-admin-layout"><form className="product-form panel" onSubmit={submit}><h2>{selected ? "Editar usuario" : "Nuevo usuario"}</h2>{selected && <div className="editing-note">Editando {selected.email}<button type="button" onClick={clearSelection}>× Cancelar</button></div>}<label>Nombre completo<input name="full_name" required value={form.full_name} onChange={updateForm} placeholder="Nombre del colaborador" /></label><label>Email<input name="email" type="email" required disabled={Boolean(selected)} value={form.email} onChange={updateForm} placeholder="usuario@empresa.com" /></label>{!selected && <label>Contraseña<input name="password" type="password" minLength="8" required value={form.password} onChange={updateForm} placeholder="Mínimo 8 caracteres" /></label>}<label>Rol<select name="role" value={form.role} onChange={updateForm}><option value="editor">Editor — productos y consultas</option><option value="admin">Administrador — acceso total</option></select></label>{message && <div className="form-message">{message}</div>}<button className="primary-link" disabled={saving}>{saving ? "Guardando…" : selected ? "Guardar cambios →" : "Crear usuario →"}</button></form><div className="panel admin-list"><div className="panel-title"><div><h2>Usuarios actuales</h2><p>Personas con acceso al panel de administración</p></div><span>{users.length} usuarios</span></div>{loading ? <p>Cargando usuarios…</p> : users.map((user) => <div className={`admin-user-row ${selected?.id === user.id ? "active-user" : ""}`} key={user.id} onClick={() => selectUser(user)} role="button" tabIndex="0"><div className="user-avatar">{(user.full_name || user.email || "U").slice(0, 1).toUpperCase()}</div><div><strong>{user.full_name || "Sin nombre"}</strong><small>{user.email || "Email pendiente"}</small></div><span className={`role-pill role-${user.role}`}>{user.role === "admin" ? "Administrador" : "Editor"}</span><div className="user-actions"><button title="Editar usuario" onClick={(event) => { event.stopPropagation(); selectUser(user); }}>✎ <span>Editar</span></button><button title="Enviar reset de contraseña" onClick={(event) => resetPassword(event, user)}>↻ <span>Resetear clave</span></button><button className="danger-button" title="Eliminar usuario" onClick={(event) => deleteUser(event, user)}>⌫ <span>Eliminar</span></button></div></div>)}</div></div></DashboardNav>;
}

function Dashboard() {
  const [metrics, setMetrics] = useState({ products: 0, newQuotes: 0, outlet: 0, monthQuotes: 0 }); const [recentQuotes, setRecentQuotes] = useState([]); const [loading, setLoading] = useState(true);
  async function loadDashboard() { if (!supabase) { setLoading(false); return; } const monthStart = new Date(); monthStart.setDate(1); monthStart.setHours(0, 0, 0, 0); const [productsResult, quotesResult, outletResult, monthResult, recentResult] = await Promise.all([supabase.from("products").select("id", { count: "exact", head: true }).eq("published", true), supabase.from("quotes").select("id", { count: "exact", head: true }).eq("status", "new"), supabase.from("products").select("id", { count: "exact", head: true }).eq("category", "outlet"), supabase.from("quotes").select("id", { count: "exact", head: true }).gte("created_at", monthStart.toISOString()), supabase.from("quotes").select("id, customer_name, created_at, total, quote_items(product_name, quantity)").order("created_at", { ascending: false }).limit(4)]); setMetrics({ products: productsResult.count || 0, newQuotes: quotesResult.count || 0, outlet: outletResult.count || 0, monthQuotes: monthResult.count || 0 }); setRecentQuotes(recentResult.data || []); setLoading(false); }
  useEffect(() => { loadDashboard(); }, []);
  if (loading) return <div className="loading">Cargando panel…</div>;
  return <DashboardNav><div className="dashboard-toolbar"><div><span className="section-kicker">Datos en tiempo real</span><h2>Resumen</h2></div><button className="refresh-button" onClick={loadDashboard}>Actualizar ↻</button></div><div className="metric-grid"><div><span>Productos publicados</span><strong>{metrics.products}</strong><small>En la tienda online</small></div><div><span>Consultas nuevas</span><strong>{metrics.newQuotes}</strong><small>Requieren atención</small></div><div><span>Productos en outlet</span><strong>{metrics.outlet}</strong><small>Con categoría outlet</small></div><div><span>Consultas este mes</span><strong>{metrics.monthQuotes}</strong><small>Solicitudes recibidas</small></div></div><div className="dashboard-columns"><div className="panel"><div className="panel-title"><h2>Actividad reciente</h2><a href="/admin/quotes">Ver todas</a></div>{recentQuotes.length ? recentQuotes.map((quote, index) => <div className="activity" key={quote.id}><i>{index + 1}</i><div><strong>Consulta de {quote.customer_name}</strong><small>{quote.quote_items?.[0]?.product_name || "Solicitud de cotización"} · {new Date(quote.created_at).toLocaleDateString("es-AR")}</small></div><span>↗</span></div>) : <p className="empty-dashboard">Todavía no hay consultas registradas.</p>}</div><div className="panel panel-highlight"><span className="section-kicker">Gestión rápida</span><h2>Administrá tu catálogo y respondé consultas.</h2><p>Los números de este panel se actualizan directamente desde Supabase.</p><a className="primary-link" href="/admin/products">Administrar productos →</a></div></div></DashboardNav>;
}

export default function App() { const path = window.location.pathname; if (path === "/admin/login") return <Login />; if (path === "/admin/reset-password") return <ResetPassword />; if (path === "/admin/products") return <AdminProducts />; if (path === "/admin/categories") return <AdminCategories />; if (path === "/admin/brands") return <AdminBrands />; if (path === "/admin/promotions") return <AdminPromotions />; if (path === "/admin/settings") return <SettingsAccess />; if (path === "/admin/quotes") return <AdminQuotes />; if (path === "/admin/users") return <AdminUsersPage />; if (path === "/checkout") return <Checkout />; if (path.startsWith("/admin")) return <Dashboard />; if (path.startsWith("/producto/")) return <ProductDetail slug={decodeURIComponent(path.split("/producto/")[1])} />; return <Landing />; }
